-- Add a reusable 150-sentence situational deck with highlighted vocabulary and audio.
insert into public.template_decks (slug, name, description, level)
values (
  'thuong-mai-hop-dong-dam-phan-150-cau',
  'Thương mại, hợp đồng và đàm phán - 150 câu',
  '150 câu tiếng Trung thực tế cho thương mại, hợp đồng và đàm phán: báo giá, chiết khấu, điều khoản, ký kết, thanh toán, công nợ, đại lý, hậu mãi và xử lý tranh chấp. Mỗi câu có pinyin, nghĩa tiếng Việt, 1-2 từ mới được highlight và audio tạo sẵn.',
  'Luyện câu'
)
on conflict (slug) do update
set name = excluded.name, description = excluded.description, level = excluded.level;

with target_deck as (
  select id from public.template_decks where slug = 'thuong-mai-hop-dong-dam-phan-150-cau'
)
insert into public.template_sentence_cards (
  template_deck_id, sentence_cn, sentence_pinyin, sentence_vi,
  vocab_json, sentence_audio_url, position
)
select
  target_deck.id, card.sentence_cn, card.sentence_pinyin,
  card.sentence_vi, card.vocab_json::jsonb,
  card.sentence_audio_url, card.position
from target_deck
cross join (
  values
    ('请您提供正式的报价单以便我们审核。', 'Qǐng nín tígōng zhèngshì de bàojià dān yǐbiàn wǒmen shěnhé.', 'Xin quý vị cung cấp bảng báo giá chính thức để chúng tôi kiểm tra.', '[{"chinese":"报价单","pinyin":"bàojià dān","meaning_vi":"bảng báo giá"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-61e90e23ba88dbb7442ba274.mp3', 1),
    ('这份报价采用美元作为货币单位。', 'Zhè fèn bàojià cǎiyòng měiyuán zuòwéi huòbì dānwèi.', 'Báo giá này sử dụng đô la Mỹ làm đơn vị tiền tệ.', '[{"chinese":"货币单位","pinyin":"huòbì dānwèi","meaning_vi":"đơn vị tiền tệ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-d151221b0ddc3c42416f9a78.mp3', 2),
    ('请问报价是否含增值税？', 'Qǐngwèn bàojià shìfǒu hán zēngzhíshuì？', 'Xin hỏi báo giá đã bao gồm thuế giá trị gia tăng chưa?', '[{"chinese":"增值税","pinyin":"zēngzhíshuì","meaning_vi":"thuế giá trị gia tăng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-28ea67908eb86fe348db1a60.mp3', 3),
    ('请告知是否存在额外的运输费用。', 'Qǐng gàozhī shìfǒu cúnzài éwài de yùnshū fèiyòng.', 'Xin cho biết có phát sinh phí vận chuyển ngoài không.', '[{"chinese":"运输费用","pinyin":"yùnshū fèiyòng","meaning_vi":"phí vận chuyển"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-719e76030d3ef5f9a16032ec.mp3', 4),
    ('报价的有效期是自发出日期起三十天。', 'Bàojià de yǒuxiàoqī shì zì fāchū rìqī qǐ sānshí tiān.', 'Thời hạn hiệu lực của báo giá là 30 ngày kể từ ngày gửi.', '[{"chinese":"有效期","pinyin":"yǒuxiàoqī","meaning_vi":"thời hạn hiệu lực"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-5b1918605fa3f0106c29d490.mp3', 5),
    ('最低订单数量是多少？', 'Zuìdī dìngdān shùliàng shì duōshǎo？', 'Số lượng đặt hàng tối thiểu là bao nhiêu?', '[{"chinese":"最低订单","pinyin":"zuìdī dìngdān","meaning_vi":"đơn hàng tối thiểu"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-fa4fe49f442b3decfd100454.mp3', 6),
    ('请问大批量采购是否享有价格优惠？', 'Qǐngwèn dà pīliàng cǎigòu shìfǒu xiǎngyǒu jiàgé yōuhuì？', 'Xin hỏi mua với số lượng lớn có được chiết khấu giá không?', '[{"chinese":"大批量采购","pinyin":"dà pīliàng cǎigòu","meaning_vi":"mua số lượng lớn"},{"chinese":"价格优惠","pinyin":"jiàgé yōuhuì","meaning_vi":"giá ưu đãi"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-0abaf68aacf105544f576a30.mp3', 7),
    ('请比较这两种报价方案的差异。', 'Qǐng bǐjiào zhè liǎng zhǒng bàojià fāng''àn de chāyì.', 'Vui lòng so sánh sự khác biệt giữa hai phương án báo giá này.', '[{"chinese":"报价方案","pinyin":"bàojià fāng''àn","meaning_vi":"phương án báo giá"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-ef0a6c85108150f9ce07fc53.mp3', 8),
    ('报价中包含了哪些费用组成部分？', 'Bàojià zhōng bāohánle nǎxiē fèiyòng zǔchéng bùfèn？', 'Báo giá bao gồm những thành phần chi phí nào?', '[{"chinese":"费用组成部分","pinyin":"fèiyòng zǔchéng bùfèn","meaning_vi":"thành phần chi phí"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-05af5f4ef66b0ce5749e8ed1.mp3', 9),
    ('请更新报价以反映最新的市场情况。', 'Qǐng gēngxīn bàojià yǐ fǎnyìng zuìxīn de shìchǎng qíngkuàng.', 'Vui lòng cập nhật báo giá phản ánh tình hình thị trường mới nhất.', '[{"chinese":"更新报价","pinyin":"gēngxīn bàojià","meaning_vi":"cập nhật báo giá"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-0ce8c4ae5837fdcb1ff32def.mp3', 10),
    ('请确认最终价格是否包括所有税费。', 'Qǐng quèrèn zuìzhōng jiàgé shìfǒu bāokuò suǒyǒu shuìfèi.', 'Xin xác nhận giá cuối cùng đã bao gồm tất cả thuế phí chưa.', '[{"chinese":"最终价格","pinyin":"zuìzhōng jiàgé","meaning_vi":"giá cuối cùng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-1fb62257b644a7b2ae6f5ec3.mp3', 11),
    ('报价单中注明了付款条件和交货时间。', 'Bàojià dān zhōng zhùmíngle fùkuǎn tiáojiàn hé jiāohuò shíjiān.', 'Trên bảng báo giá có ghi rõ điều kiện thanh toán và thời gian giao hàng.', '[{"chinese":"付款条件","pinyin":"fùkuǎn tiáojiàn","meaning_vi":"điều kiện thanh toán"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-9fb621d086a9a1282fcdfdb4.mp3', 12),
    ('您能说明价格是否含运输保险费用吗？', 'Nín néng shuōmíng jiàgé shìfǒu hán yùnshū bǎoxiǎn fèiyòng ma？', 'Quý vị có thể cho biết giá có bao gồm phí bảo hiểm vận chuyển không?', '[{"chinese":"运输保险","pinyin":"yùnshū bǎoxiǎn","meaning_vi":"bảo hiểm vận chuyển"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-ef8abe45e2fb05dcbb9bcf8d.mp3', 13),
    ('请问每批最小订购量是多少？', 'Qǐngwèn měi pī zuìxiǎo dìnggòu liàng shì duōshǎo？', 'Xin hỏi số lượng đặt tối thiểu mỗi lô hàng là bao nhiêu?', '[{"chinese":"最小订购量","pinyin":"zuìxiǎo dìnggòu liàng","meaning_vi":"số lượng đặt tối thiểu"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-59ac9fb17a9a46ce2e846c6c.mp3', 14),
    ('此价格基于当前市场汇率计算。', 'Cǐ jiàgé jīyú dāngqián shìchǎng huìlǜ jìsuàn.', 'Giá này được tính dựa trên tỷ giá thị trường hiện tại.', '[{"chinese":"汇率","pinyin":"huìlǜ","meaning_vi":"tỷ giá hối đoái"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-a9dc048e4da23966a373f026.mp3', 15),
    ('此报价暂时不包含后续维护费用。', 'Cǐ bàojià zànshí bù bāohán hòuxù wéihù fèiyòng.', 'Báo giá này hiện chưa bao gồm phí bảo trì sau bán hàng.', '[{"chinese":"维护费用","pinyin":"wéihù fèiyòng","meaning_vi":"phí bảo trì"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-7d38f4c113c9c58acbd73048.mp3', 16),
    ('折扣率会根据订单数量相应调整。', 'Zhékòu lǜ huì gēnjù dìngdān shùliàng xiāngyìng tiáozhěng.', 'Tỷ lệ chiết khấu sẽ được điều chỉnh tương ứng theo số lượng đơn hàng.', '[{"chinese":"折扣率","pinyin":"zhékòu lǜ","meaning_vi":"tỷ lệ chiết khấu"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-dcd574ffc31b4892c12b1458.mp3', 17),
    ('报价中未包含关税费用，请您注意。', 'Bàojià zhōng wèi bāohán guānshuì fèiyòng, qǐng nín zhùyì.', 'Báo giá chưa bao gồm phí thuế hải quan, xin quý vị lưu ý.', '[{"chinese":"关税","pinyin":"guānshuì","meaning_vi":"thuế hải quan"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-6bbe80a1a489637057185302.mp3', 18),
    ('我们可以根据您的需求提供定制报价。', 'Wǒmen kěyǐ gēnjù nín de xūqiú tígōng dìngzhì bàojià.', 'Chúng tôi có thể cung cấp báo giá tùy chỉnh theo nhu cầu của quý vị.', '[{"chinese":"定制报价","pinyin":"dìngzhì bàojià","meaning_vi":"báo giá tùy chỉnh"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-685d8a4f60867739ef2b8c97.mp3', 19),
    ('此报价包含了材料费、人工费和运输费。', 'Cǐ bàojià bāohánle cáiliào fèi、réngōng fèi hé yùnshū fèi.', 'Báo giá này bao gồm chi phí nguyên liệu, nhân công và vận chuyển.', '[{"chinese":"材料费","pinyin":"cáiliào fèi","meaning_vi":"chi phí nguyên liệu"},{"chinese":"人工费","pinyin":"réngōng fèi","meaning_vi":"chi phí nhân công"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-0e75294599d55824eafc31eb.mp3', 20),
    ('请确认报价是否含有任何隐藏费用。', 'Qǐng quèrèn bàojià shìfǒu hányǒu rènhé yǐncáng fèiyòng.', 'Xin xác nhận báo giá có chứa bất kỳ phí ẩn nào không.', '[{"chinese":"隐藏费用","pinyin":"yǐncáng fèiyòng","meaning_vi":"phí ẩn"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-ee23dc26ce49b8b04d777a88.mp3', 21),
    ('根据订购量不同，价格会有一定幅度变动。', 'Gēnjù dìnggòu liàng bùtóng, jiàgé huì yǒu yīdìng fúdù biàndòng.', 'Giá cả sẽ thay đổi trong một phạm vi nhất định tùy theo số lượng đặt hàng.', '[{"chinese":"幅度","pinyin":"fúdù","meaning_vi":"biên độ, mức"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-99c6521e3a6b48fc2afea974.mp3', 22),
    ('您需要的报价将在两日内发送。', 'Nín xūyào de bàojià jiàng zài liǎng rì nèi fāsòng.', 'Báo giá quý vị cần sẽ được gửi trong vòng hai ngày.', '[{"chinese":"发送","pinyin":"fāsòng","meaning_vi":"gửi đi"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-ed5a7f5358c012456f0fd740.mp3', 23),
    ('报价已更新，请查收最新版本。', 'Bàojià yǐ gēngxīn, qǐng cháshōu zuìxīn bǎnběn.', 'Báo giá đã được cập nhật, xin kiểm tra phiên bản mới nhất.', '[{"chinese":"最新版本","pinyin":"zuìxīn bǎnběn","meaning_vi":"phiên bản mới nhất"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-f7c54b9fa58c9d2c28ff4db2.mp3', 24),
    ('请确认报价是否需要预付款项。', 'Qǐng quèrèn bàojià shìfǒu xūyào yùfù kuǎnxiàng.', 'Xin xác nhận báo giá có yêu cầu đặt cọc không.', '[{"chinese":"预付款项","pinyin":"yùfù kuǎnxiàng","meaning_vi":"khoản tiền đặt cọc"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-aa5dc27c322be726f575969d.mp3', 25),
    ('针对大批量订单，我们可以提供更高的折扣率。', 'Zhēnduì dà pīliàng dìngdān, wǒmen kěyǐ tígōng gèng gāo de zhékòu lǜ.', 'Đối với đơn hàng số lượng lớn, chúng tôi có thể cung cấp mức chiết khấu cao hơn.', '[{"chinese":"大批量","pinyin":"dà pīliàng","meaning_vi":"số lượng lớn"},{"chinese":"折扣率","pinyin":"zhékòu lǜ","meaning_vi":"tỷ lệ chiết khấu"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-26dcfbbadb271ddd233fd6e8.mp3', 26),
    ('请问您希望的目标价格是多少？', 'Qǐngwèn nín xīwàng de mùbiāo jiàgé shì duōshǎo？', 'Xin hỏi giá mục tiêu mà quý khách mong muốn là bao nhiêu?', '[{"chinese":"目标价格","pinyin":"mùbiāo jiàgé","meaning_vi":"giá mục tiêu"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-5045926fd782572dfd002266.mp3', 27),
    ('折扣仅限于首次合作订单，不适用于续单。', 'Zhékòu jǐn xiànyú shǒucì hézuò dìngdān, bù shìyòng yú xù dān.', 'Chiết khấu chỉ áp dụng cho đơn hàng hợp tác lần đầu, không áp dụng cho đơn tiếp theo.', '[{"chinese":"首次合作","pinyin":"shǒucì hézuò","meaning_vi":"hợp tác lần đầu"},{"chinese":"续单","pinyin":"xù dān","meaning_vi":"đơn hàng tiếp theo"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-5f4d9f2c40adbd75de1da632.mp3', 28),
    ('如果您能提前付款，我们可以考虑额外的折扣。', 'Rúguǒ nín néng tíqián fùkuǎn, wǒmen kěyǐ kǎolǜ éwài de zhékòu.', 'Nếu quý khách thanh toán trước, chúng tôi có thể xem xét chiết khấu thêm.', '[{"chinese":"提前付款","pinyin":"tíqián fùkuǎn","meaning_vi":"thanh toán trước"},{"chinese":"额外","pinyin":"éwài","meaning_vi":"thêm, ngoài dự kiến"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-ef5d769f6d681b3e25fc1b5c.mp3', 29),
    ('请您确认这些折扣是否可以叠加使用。', 'Qǐng nín quèrèn zhèxiē zhékòu shìfǒu kěyǐ diéjiā shǐyòng.', 'Xin vui lòng xác nhận các chiết khấu này có thể cộng dồn được không.', '[{"chinese":"叠加","pinyin":"diéjiā","meaning_vi":"cộng dồn"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-1473da818ec156523a74c573.mp3', 30),
    ('若订单数量增加，我们会适当调整价格。', 'Ruò dìngdān shùliàng zēngjiā, wǒmen huì shìdàng tiáozhěng jiàgé.', 'Nếu số lượng đơn hàng tăng, chúng tôi sẽ điều chỉnh giá hợp lý.', '[{"chinese":"订单数量","pinyin":"dìngdān shùliàng","meaning_vi":"số lượng đơn hàng"},{"chinese":"调整","pinyin":"tiáozhěng","meaning_vi":"điều chỉnh"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-0efa6a943a3c5d41d522ebcd.mp3', 31),
    ('我们希望双方在价格上都能有适度的让步。', 'Wǒmen xīwàng shuāngfāng zài jiàgé shàng dōu néng yǒu shìdù de ràngbù.', 'Chúng tôi mong hai bên có sự nhượng bộ hợp lý về giá cả.', '[{"chinese":"让步","pinyin":"ràngbù","meaning_vi":"nhượng bộ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-5bac252de39c2c869625ca84.mp3', 32),
    ('这份报价包含了运输和安装服务费用。', 'Zhè fèn bàojià bāohánle yùnshū hé ānzhuāng fúwù fèiyòng.', 'Báo giá này đã bao gồm chi phí vận chuyển và lắp đặt.', '[{"chinese":"运输","pinyin":"yùnshū","meaning_vi":"vận chuyển"},{"chinese":"安装","pinyin":"ānzhuāng","meaning_vi":"lắp đặt"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-6cc14be21ee32a3755305bf4.mp3', 33),
    ('是否能将交货时间缩短以满足我们的需求？', 'Shìfǒu néng jiāng jiāohuò shíjiān suōduǎn yǐ mǎnzú wǒmen de xūqiú？', 'Có thể rút ngắn thời gian giao hàng để đáp ứng yêu cầu của chúng tôi không?', '[{"chinese":"交货时间","pinyin":"jiāohuò shíjiān","meaning_vi":"thời gian giao hàng"},{"chinese":"缩短","pinyin":"suōduǎn","meaning_vi":"rút ngắn"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-4455eaadcf8466bd2ad86de7.mp3', 34),
    ('针对长期合作客户，我们愿意提供额外优惠。', 'Zhēnduì chángqī hézuò kèhù, wǒmen yuànyì tígōng éwài yōuhuì.', 'Đối với khách hàng hợp tác lâu dài, chúng tôi sẵn sàng cung cấp ưu đãi thêm.', '[{"chinese":"长期合作","pinyin":"chángqī hézuò","meaning_vi":"hợp tác lâu dài"},{"chinese":"优惠","pinyin":"yōuhuì","meaning_vi":"ưu đãi"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-cedceed1d281e8c93403858d.mp3', 35),
    ('您可以接受以提高数量来交换更优惠的价格吗？', 'Nín kěyǐ jiēshòu yǐ tígāo shùliàng lái jiāohuàn gèng yōuhuì de jiàgé ma？', 'Quý khách có thể chấp nhận đổi giá lấy số lượng tăng để có giá ưu đãi hơn không?', '[{"chinese":"交换","pinyin":"jiāohuàn","meaning_vi":"đổi, trao đổi"},{"chinese":"优惠","pinyin":"yōuhuì","meaning_vi":"ưu đãi"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-be303695b21d57cc028975b7.mp3', 36),
    ('如果能缩短付款期限，我们愿意考虑更低价格。', 'Rúguǒ néng suōduǎn fùkuǎn qīxiàn, wǒmen yuànyì kǎolǜ gèng dī jiàgé.', 'Nếu có thể rút ngắn thời hạn thanh toán, chúng tôi sẵn sàng xem xét mức giá thấp hơn.', '[{"chinese":"付款期限","pinyin":"fùkuǎn qīxiàn","meaning_vi":"thời hạn thanh toán"},{"chinese":"考虑","pinyin":"kǎolǜ","meaning_vi":"xem xét"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-b97acf8cfc3c041bfa021e60.mp3', 37),
    ('请提出您认为合理的价格调整方案。', 'Qǐng tíchū nín rènwéi hélǐ de jiàgé tiáozhěng fāng''àn.', 'Xin đề xuất phương án điều chỉnh giá bạn cho là hợp lý.', '[{"chinese":"合理","pinyin":"hélǐ","meaning_vi":"hợp lý"},{"chinese":"调整方案","pinyin":"tiáozhěng fāng''àn","meaning_vi":"phương án điều chỉnh"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-d3649d739eebdb749435c8b1.mp3', 38),
    ('我们可以在合同中明确优惠的适用条件。', 'Wǒmen kěyǐ zài hétóng zhōng míngquè yōuhuì de shìyòng tiáojiàn.', 'Chúng tôi có thể ghi rõ điều kiện áp dụng ưu đãi trong hợp đồng.', '[{"chinese":"合同","pinyin":"hétóng","meaning_vi":"hợp đồng"},{"chinese":"适用条件","pinyin":"shìyòng tiáojiàn","meaning_vi":"điều kiện áp dụng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-08ade92ad620a084154ee823.mp3', 39),
    ('如果订单提前确认，我们可以优先安排生产。', 'Rúguǒ dìngdān tíqián quèrèn, wǒmen kěyǐ yōuxiān ānpái shēngchǎn.', 'Nếu đơn hàng được xác nhận sớm, chúng tôi sẽ ưu tiên bố trí sản xuất.', '[{"chinese":"提前确认","pinyin":"tíqián quèrèn","meaning_vi":"xác nhận trước"},{"chinese":"优先","pinyin":"yōuxiān","meaning_vi":"ưu tiên"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-e0ca812c02dd6b1a9f36068a.mp3', 40),
    ('您的支付条件是否可以适当延长？', 'Nín de zhīfù tiáojiàn shìfǒu kěyǐ shìdàng yáncháng？', 'Điều kiện thanh toán của quý khách có thể được gia hạn thích hợp không?', '[{"chinese":"支付条件","pinyin":"zhīfù tiáojiàn","meaning_vi":"điều kiện thanh toán"},{"chinese":"延长","pinyin":"yáncháng","meaning_vi":"gia hạn"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-e3e8894b3abf19a930bbd760.mp3', 41),
    ('请问是否可以对早期付款给予优惠？', 'Qǐngwèn shìfǒu kěyǐ duì zǎoqī fùkuǎn jǐyǔ yōuhuì？', 'Xin hỏi có thể ưu đãi cho thanh toán sớm không?', '[{"chinese":"早期付款","pinyin":"zǎoqī fùkuǎn","meaning_vi":"thanh toán sớm"},{"chinese":"给予优惠","pinyin":"jǐyǔ yōuhuì","meaning_vi":"cấp ưu đãi"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-c0a60799cacc0599939a3959.mp3', 42),
    ('这项折扣仅适用于特定型号产品。', 'Zhè xiàng zhékòu jǐn shìyòng yú tèdìng xínghào chǎnpǐn.', 'Chiết khấu này chỉ áp dụng cho sản phẩm model cụ thể.', '[{"chinese":"特定型号","pinyin":"tèdìng xínghào","meaning_vi":"model cụ thể"},{"chinese":"适用","pinyin":"shìyòng","meaning_vi":"áp dụng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-738a24554c619b0feb7ffd44.mp3', 43),
    ('为了达成协议，我们愿意在价格上做出让步。', 'Wèile dáchéng xiéyì, wǒmen yuànyì zài jiàgé shàng zuòchū ràngbù.', 'Để đạt được thỏa thuận, chúng tôi sẵn lòng nhượng bộ về giá cả.', '[{"chinese":"达成协议","pinyin":"dáchéng xiéyì","meaning_vi":"đạt thỏa thuận"},{"chinese":"让步","pinyin":"ràngbù","meaning_vi":"nhượng bộ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-0a2827d15ebe3171f1cf796a.mp3', 44),
    ('请确认是否需要补充合同条款以涵盖优惠内容。', 'Qǐng quèrèn shìfǒu xūyào bǔchōng hétóng tiáokuǎn yǐ hán''gài yōuhuì nèiróng.', 'Xin xác nhận có cần bổ sung điều khoản hợp đồng để bao gồm nội dung ưu đãi không.', '[{"chinese":"补充","pinyin":"bǔchōng","meaning_vi":"bổ sung"},{"chinese":"涵盖","pinyin":"hán''gài","meaning_vi":"bao gồm"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-8a57749a669feff2288eb01f.mp3', 45),
    ('请提供一个可行的价格调整备选方案。', 'Qǐng tígōng yīgè kěxíng de jiàgé tiáozhěng bèixuǎn fāng''àn.', 'Xin cung cấp một phương án điều chỉnh giá khả thi thay thế.', '[{"chinese":"备选方案","pinyin":"bèixuǎn fāng''àn","meaning_vi":"phương án thay thế"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-132d99a8b16318353301fc3b.mp3', 46),
    ('我们建议分批付款以换取更好的折扣。', 'Wǒmen jiànyì fēnpī fùkuǎn yǐ huànqǔ gèng hǎo de zhékòu.', 'Chúng tôi đề nghị thanh toán theo từng đợt để đổi lấy chiết khấu tốt hơn.', '[{"chinese":"分批付款","pinyin":"fēnpī fùkuǎn","meaning_vi":"thanh toán theo từng đợt"},{"chinese":"换取","pinyin":"huànqǔ","meaning_vi":"đổi lấy"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-e75a7824deae18a8a70ff531.mp3', 47),
    ('如需延长优惠期限，请及时告知我们。', 'Rú xū yáncháng yōuhuì qīxiàn, qǐng jíshí gàozhī wǒmen.', 'Nếu cần gia hạn thời hạn ưu đãi, xin thông báo kịp thời cho chúng tôi.', '[{"chinese":"优惠期限","pinyin":"yōuhuì qīxiàn","meaning_vi":"thời hạn ưu đãi"},{"chinese":"及时","pinyin":"jíshí","meaning_vi":"kịp thời"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-b22cd4579aa3b26c1db84bde.mp3', 48),
    ('我们希望本次谈判能够达成双赢的结果。', 'Wǒmen xīwàng běncì tánpàn nénggòu dáchéng shuāngyíng de jiéguǒ.', 'Chúng tôi hy vọng cuộc đàm phán lần này đạt kết quả đôi bên cùng có lợi.', '[{"chinese":"谈判","pinyin":"tánpàn","meaning_vi":"đàm phán"},{"chinese":"双赢","pinyin":"shuāngyíng","meaning_vi":"đôi bên cùng thắng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-0802a5a06c6a94c3520c538d.mp3', 49),
    ('请问是否接受以增加采购量换取价格优惠？', 'Qǐngwèn shìfǒu jiēshòu yǐ zēngjiā cǎigòu liàng huànqǔ jiàgé yōuhuì？', 'Xin hỏi có chấp nhận đổi lượng mua lớn hơn để lấy ưu đãi giá không?', '[{"chinese":"采购量","pinyin":"cǎigòu liàng","meaning_vi":"lượng mua"},{"chinese":"价格优惠","pinyin":"jiàgé yōuhuì","meaning_vi":"ưu đãi giá"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-0c6525c91552febc62f94573.mp3', 50),
    ('请您先审核这份合同草案的条款内容。', 'Qǐng nín xiān shěnhé zhè fèn hé​tóng cǎo''àn de tiáokuǎn nèiróng.', 'Xin quý vị vui lòng rà soát nội dung các điều khoản trong dự thảo hợp đồng này trước.', '[{"chinese":"合同草案","pinyin":"hé​tóng cǎo''àn","meaning_vi":"dự thảo hợp đồng"},{"chinese":"条款","pinyin":"tiáokuǎn","meaning_vi":"điều khoản"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-cff4ac3a6ef03f6c8e3f5258.mp3', 51),
    ('请明确双方在合作中的权利与义务范围。', 'Qǐng míngquè shuāngfāng zài hézuò zhōng de quánlì yǔ yìwù fànwéi.', 'Vui lòng làm rõ phạm vi quyền và nghĩa vụ của hai bên trong hợp tác.', '[{"chinese":"权利","pinyin":"quánlì","meaning_vi":"quyền lợi"},{"chinese":"义务","pinyin":"yìwù","meaning_vi":"nghĩa vụ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-66db4fdcaadcc76d94f230f7.mp3', 52),
    ('双方应就验收标准达成一致意见。', 'Shuāngfāng yīng jiù yànshōu biāozhǔn dáchéng yīzhì yìjiàn.', 'Hai bên cần thống nhất ý kiến về tiêu chuẩn nghiệm thu.', '[{"chinese":"验收标准","pinyin":"yànshōu biāozhǔn","meaning_vi":"tiêu chuẩn nghiệm thu"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-ab047e5df40e3c5264d812a6.mp3', 53),
    ('合同中需增加一条保密条款以保护信息安全。', 'Hé​tóng zhōng xū zēngjiā yītiáo bǎomì tiáokuǎn yǐ bǎohù xìnxī ānquán.', 'Cần bổ sung một điều khoản bảo mật trong hợp đồng để bảo vệ an toàn thông tin.', '[{"chinese":"保密条款","pinyin":"bǎomì tiáokuǎn","meaning_vi":"điều khoản bảo mật"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-25bae241b2552833260ce69a.mp3', 54),
    ('请对合同中有关违约的条款进行修订。', 'Qǐng duì hé​tóng zhōng yǒuguān wéiyuē de tiáokuǎn jìnxíng xiūdìng.', 'Xin vui lòng sửa đổi các điều khoản liên quan đến vi phạm hợp đồng.', '[{"chinese":"违约","pinyin":"wéiyuē","meaning_vi":"vi phạm hợp đồng"},{"chinese":"修订","pinyin":"xiūdìng","meaning_vi":"sửa đổi"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-78cd1af2c4297cb9a3660c43.mp3', 55),
    ('我们需要明确合同终止的条件和程序。', 'Wǒmen xūyào míngquè hé​tóng zhōngzhǐ de tiáojiàn hé chéngxù.', 'Chúng tôi cần làm rõ điều kiện và thủ tục chấm dứt hợp đồng.', '[{"chinese":"终止","pinyin":"zhōngzhǐ","meaning_vi":"chấm dứt"},{"chinese":"条件","pinyin":"tiáojiàn","meaning_vi":"điều kiện"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-d64cda5600f9e0f9e57c2c39.mp3', 56),
    ('请提供合同附件的修改建议。', 'Qǐng tígōng hé​tóng fùjiàn de xiūgǎi jiànyì.', 'Xin vui lòng cung cấp đề xuất sửa đổi phụ lục hợp đồng.', '[{"chinese":"附件","pinyin":"fùjiàn","meaning_vi":"phụ lục"},{"chinese":"修改","pinyin":"xiūgǎi","meaning_vi":"sửa đổi"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-a863657b832936f2963af013.mp3', 57),
    ('合同签署时请双方盖章确认。', 'Hé​tóng qiānshǔ shí qǐng shuāngfāng gàizhāng quèrèn.', 'Khi ký hợp đồng, xin hai bên đóng dấu xác nhận.', '[{"chinese":"签署","pinyin":"qiānshǔ","meaning_vi":"ký kết"},{"chinese":"盖章","pinyin":"gàizhāng","meaning_vi":"đóng dấu"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-4135c0f14a2a925f8e2d6363.mp3', 58),
    ('请确认合同生效的具体日期。', 'Qǐng quèrèn hé​tóng shēngxiào de jùtǐ rìqī.', 'Xin xác nhận ngày có hiệu lực cụ thể của hợp đồng.', '[{"chinese":"生效","pinyin":"shēngxiào","meaning_vi":"hiệu lực"},{"chinese":"日期","pinyin":"rìqī","meaning_vi":"ngày tháng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-40c1a33a00373f6c7e81d15c.mp3', 59),
    ('希望双方能协商延长合同的有效期限。', 'Xīwàng shuāngfāng néng xiéshāng yáncháng hé​tóng de yǒuxiào qīxiàn.', 'Hy vọng hai bên có thể thương lượng gia hạn hiệu lực hợp đồng.', '[{"chinese":"延长","pinyin":"yáncháng","meaning_vi":"gia hạn"},{"chinese":"有效期限","pinyin":"yǒuxiào qīxiàn","meaning_vi":"thời hiệu, thời hạn hợp đồng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-c0fa0c7289a5861cad28516a.mp3', 60),
    ('请审阅合同条款确保符合双方利益。', 'Qǐng shěnyuè hé​tóng tiáokuǎn quèbǎo fúhé shuāngfāng lìyì.', 'Xin kiểm tra các điều khoản hợp đồng để đảm bảo phù hợp với lợi ích của hai bên.', '[{"chinese":"审阅","pinyin":"shěnyuè","meaning_vi":"xem xét, rà soát"},{"chinese":"利益","pinyin":"lìyì","meaning_vi":"lợi ích"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-a23e2ef1bbf2628ede667149.mp3', 61),
    ('为了合作顺利，请明确双方权责分配。', 'Wèile hézuò shùnlì, qǐng míngquè shuāngfāng quánzé fēnpèi.', 'Để hợp tác thuận lợi, xin làm rõ phân chia quyền và trách nhiệm của hai bên.', '[{"chinese":"权责","pinyin":"quánzé","meaning_vi":"quyền và trách nhiệm"},{"chinese":"分配","pinyin":"fēnpèi","meaning_vi":"phân phối, phân chia"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-83b0b5d15c3fff0006c5bb11.mp3', 62),
    ('合同验收标准应符合行业规范要求。', 'Hé​tóng yànshōu biāozhǔn yīng fúhé hángyè guīfàn yāoqiú.', 'Tiêu chuẩn nghiệm thu hợp đồng cần tuân thủ quy phạm ngành nghề.', '[{"chinese":"行业规范","pinyin":"hángyè guīfàn","meaning_vi":"quy chuẩn ngành"},{"chinese":"要求","pinyin":"yāoqiú","meaning_vi":"yêu cầu"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-58dccfe7fcf83abc4144286d.mp3', 63),
    ('请确保合同中的保密义务内容详尽清晰。', 'Qǐng quèbǎo hé​tóng zhōng de bǎomì yìwù nèiróng xiángjìn qīngxī.', 'Xin đảm bảo nội dung nghĩa vụ bảo mật trong hợp đồng rõ ràng và đầy đủ.', '[{"chinese":"保密义务","pinyin":"bǎomì yìwù","meaning_vi":"nghĩa vụ bảo mật"},{"chinese":"详尽","pinyin":"xiángjìn","meaning_vi":"chi tiết, đầy đủ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-31678c54ae0852fdb8197483.mp3', 64),
    ('对于违约责任，希望能合理分摊。', 'Duìyú wéiyuē zérèn, xīwàng néng hélǐ fēntān.', 'Về trách nhiệm vi phạm hợp đồng, mong được phân chia hợp lý.', '[{"chinese":"违约责任","pinyin":"wéiyuē zérèn","meaning_vi":"trách nhiệm vi phạm hợp đồng"},{"chinese":"合理","pinyin":"hélǐ","meaning_vi":"hợp lý"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-199a4171a80514aeb78a6b5b.mp3', 65),
    ('建议明确合同解除的程序与条件。', 'Jiànyì míngquè hé​tóng jiěchú de chéngxù yǔ tiáojiàn.', 'Đề nghị làm rõ thủ tục và điều kiện giải chấm dứt hợp đồng.', '[{"chinese":"解除","pinyin":"jiěchú","meaning_vi":"giải trừ, chấm dứt"},{"chinese":"程序","pinyin":"chéngxù","meaning_vi":"thủ tục"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-cb92faca1afac7a58aff39c3.mp3', 66),
    ('请提供最新修订的合同附件版本。', 'Qǐng tígōng zuìxīn xiūdìng de hé​tóng fùjiàn bǎnběn.', 'Xin vui lòng cung cấp phiên bản phụ lục hợp đồng đã được sửa đổi mới nhất.', '[{"chinese":"修订","pinyin":"xiūdìng","meaning_vi":"sửa đổi"},{"chinese":"附件","pinyin":"fùjiàn","meaning_vi":"phụ lục"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-be0ad7b9b5cac79dbdf9aae0.mp3', 67),
    ('合同签字盖章后请返回一份扫描件。', 'Hé​tóng qiānzì gàizhāng hòu qǐng fǎnhuí yī fèn sǎomiáo jiàn.', 'Sau khi ký tên và đóng dấu hợp đồng, xin vui lòng gửi lại một bản quét.', '[{"chinese":"扫描件","pinyin":"sǎomiáo jiàn","meaning_vi":"bản sao quét"},{"chinese":"签字","pinyin":"qiānzì","meaning_vi":"ký tên"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-6c1ba9090c5a92b2d2dc6413.mp3', 68),
    ('请告知合同何时正式生效。', 'Qǐng gàozhī hé​tóng héshí zhèngshì shēngxiào.', 'Xin thông báo hợp đồng chính thức có hiệu lực khi nào.', '[{"chinese":"正式","pinyin":"zhèngshì","meaning_vi":"chính thức"},{"chinese":"生效","pinyin":"shēngxiào","meaning_vi":"hiệu lực"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-8b7cffc67c727f013e6fbbab.mp3', 69),
    ('关于合同续签，建议提前一个月通知对方。', 'Guānyú hé​tóng xùqiān, jiànyì tíqián yī gè yuè tōngzhī duìfāng.', 'Về việc gia hạn hợp đồng, đề nghị thông báo cho đối phương trước một tháng.', '[{"chinese":"续签","pinyin":"xùqiān","meaning_vi":"gia hạn hợp đồng"},{"chinese":"提前","pinyin":"tíqián","meaning_vi":"trước hạn"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-943a4f61852a4609513d46f6.mp3', 70),
    ('请再次确认所有合同条款是否准确无误。', 'Qǐng zài cì quèrèn suǒyǒu hé​tóng tiáokuǎn shìfǒu zhǔnquè wúwù.', 'Xin xác nhận lại tất cả các điều khoản hợp đồng có chính xác và không sai sót hay không.', '[{"chinese":"准确","pinyin":"zhǔnquè","meaning_vi":"chính xác"},{"chinese":"无误","pinyin":"wúwù","meaning_vi":"không có sai sót"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-074cbe780dce7547e8356f92.mp3', 71),
    ('请说明双方在合同中的责任分工。', 'Qǐng shuōmíng shuāngfāng zài hé​tóng zhōng de zérèn fēngōng.', 'Xin vui lòng làm rõ sự phân công trách nhiệm của hai bên trong hợp đồng.', '[{"chinese":"责任","pinyin":"zérèn","meaning_vi":"trách nhiệm"},{"chinese":"分工","pinyin":"fēngōng","meaning_vi":"phân công"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-8aa4a927ca04d0dbcc49da1d.mp3', 72),
    ('合同验收应符合双方商定的质量标准。', 'Hé​tóng yànshōu yīng fúhé shuāngfāng shāngdìng de zhìliàng biāozhǔn.', 'Nghiệm thu hợp đồng cần đáp ứng tiêu chuẩn chất lượng hai bên đã thỏa thuận.', '[{"chinese":"质量标准","pinyin":"zhìliàng biāozhǔn","meaning_vi":"tiêu chuẩn chất lượng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-5d8d03af3b8d81c69fe59727.mp3', 73),
    ('增补的保密条款请确认后签署。', 'Zēngbǔ de bǎomì tiáokuǎn qǐng quèrèn hòu qiānshǔ.', 'Đề nghị xác nhận và ký vào điều khoản bảo mật được bổ sung.', '[{"chinese":"增补","pinyin":"zēngbǔ","meaning_vi":"bổ sung"},{"chinese":"保密条款","pinyin":"bǎomì tiáokuǎn","meaning_vi":"điều khoản bảo mật"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-21910cebad6da03550ffceee.mp3', 74),
    ('我们希望合理分摊因违约产生的损失。', 'Wǒmen xīwàng hélǐ fēntān yīn wéiyuē chǎnshēng de sǔnshī.', 'Chúng tôi mong muốn chia sẻ hợp lý tổn thất do vi phạm hợp đồng gây ra.', '[{"chinese":"损失","pinyin":"sǔnshī","meaning_vi":"tổn thất"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-e1aa8e7ae09944b400adb8ad.mp3', 75),
    ('请确认您的订单内容和规格是否准确。', 'Qǐng quèrèn nín de dìngdān nèiróng hé guīgé shìfǒu zhǔnquè.', 'Vui lòng xác nhận nội dung và *đơn hàng* của quý khách có chính xác không.', '[{"chinese":"订单","pinyin":"dìngdān","meaning_vi":"đơn hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-6df75c7cf301dec209fe53fa.mp3', 76),
    ('我们已收到您的定金付款，请核实到账情况。', 'Wǒmen yǐ shōudào nín de dìngjīn fùkuǎn, qǐng héshí dào zhàng qíngkuàng.', 'Chúng tôi đã nhận được tiền *đặt cọc* của quý khách, xin vui lòng xác minh tình trạng đã về tài khoản.', '[{"chinese":"定金","pinyin":"dìngjīn","meaning_vi":"tiền đặt cọc"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-a680f372a6044ba5ed850a18.mp3', 77),
    ('请确认付款计划是否符合双方约定的时间表。', 'Qǐng quèrèn fùkuǎn jìhuà shìfǒu fúhé shuāngfāng yuēdìng de shíjiānbiǎo.', 'Vui lòng xác nhận kế hoạch *thanh toán* có phù hợp với lịch trình đã thỏa thuận giữa hai bên không.', '[{"chinese":"付款计划","pinyin":"fùkuǎn jìhuà","meaning_vi":"kế hoạch thanh toán"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-77c1116bb460fd93e4a338a7.mp3', 78),
    ('请提供用于收款账户的准确银行信息。', 'Qǐng tígōng yòng yú shōukuǎn zhànghù de zhǔnquè yínháng xìnxī.', 'Vui lòng cung cấp thông tin ngân hàng chính xác của *tài khoản nhận tiền*.', '[{"chinese":"账户","pinyin":"zhànghù","meaning_vi":"tài khoản"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-dfb43fa5d0bf3ee12b2f12c7.mp3', 79),
    ('请发送付款凭证以便我们核对账务。', 'Qǐng fāsòng fùkuǎn píngzhèng yǐbiàn wǒmen héduì zhàngwù.', 'Xin vui lòng gửi *chứng từ thanh toán* để chúng tôi đối soát công nợ.', '[{"chinese":"付款凭证","pinyin":"fùkuǎn píngzhèng","meaning_vi":"chứng từ thanh toán"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-d694176c8d0edd94bf2be838.mp3', 80),
    ('请您确认是否需要开具增值税发票。', 'Qǐng nín quèrèn shìfǒu xūyào kāijù zēngzhíshuì fāpiào.', 'Xin quý khách xác nhận có cần xuất *hóa đơn* giá trị gia tăng hay không.', '[{"chinese":"发票","pinyin":"fāpiào","meaning_vi":"hóa đơn"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-42cec75a76be893d9fbd41ec.mp3', 81),
    ('请核实预定的交货日期是否仍然有效。', 'Qǐng héshí yùdìng de jiāohuò rìqī shìfǒu réngrán yǒuxiào.', 'Vui lòng xác nhận *lịch giao hàng* đã đặt có còn hiệu lực không.', '[{"chinese":"交货日期","pinyin":"jiāohuò rìqī","meaning_vi":"lịch giao hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-049954d3d4033a71af70fa9f.mp3', 82),
    ('如需变更订单数量，请提前通知以便调整。', 'Rú xū biàngēng dìngdān shùliàng, qǐng tíqián tōngzhī yǐbiàn tiáozhěng.', 'Nếu cần thay đổi *số lượng* đơn hàng, xin vui lòng báo trước để điều chỉnh.', '[{"chinese":"数量","pinyin":"shùliàng","meaning_vi":"số lượng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-c7a900b5e912d16e95807480.mp3', 83),
    ('请提供订单执行的最新进度报告。', 'Qǐng tígōng dìngdān zhíxíng de zuìxīn jìndù bàogào.', 'Vui lòng cung cấp báo cáo *tiến độ* thực hiện đơn hàng mới nhất.', '[{"chinese":"进度","pinyin":"jìndù","meaning_vi":"tiến độ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-5e0093acb40e1a1b89fdebb8.mp3', 84),
    ('因不可抗力，交货时间将略有延迟，敬请谅解。', 'Yīn bùkě kànglì, jiāohuò shíjiān jiāng lüèyǒu yánchí, jìng qǐng liàngjiě.', 'Do yếu tố bất khả kháng, *thời gian giao hàng* sẽ chậm một chút, mong quý khách thông cảm.', '[{"chinese":"交货时间","pinyin":"jiāohuò shíjiān","meaning_vi":"thời gian giao hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-5f520b792054cc5b8fa10b42.mp3', 85),
    ('请确认您已收到全部货物且无质量问题。', 'Qǐng quèrèn nín yǐ shōudào quánbù huòwù qiě wú zhìliàng wèntí.', 'Vui lòng xác nhận đã nhận đủ hàng và không có vấn đề về *chất lượng*.', '[{"chinese":"质量问题","pinyin":"zhìliàng wèntí","meaning_vi":"vấn đề chất lượng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-0a1ca28f9a8808335b675bf0.mp3', 86),
    ('请确认所有应付账款已结清无剩余。', 'Qǐng quèrèn suǒyǒu yīng fù zhàngkuǎn yǐ jiéqīng wú shèngyú.', 'Xin xác nhận tất cả các khoản *công nợ* đã thanh toán hết không còn dư.', '[{"chinese":"账款","pinyin":"zhàngkuǎn","meaning_vi":"công nợ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-4db13471c0814098207c3832.mp3', 87),
    ('请确认是否完成了本次订单的全部付款义务。', 'Qǐng quèrèn shìfǒu wánchéngle běncì dìngdān de quánbù fùkuǎn yìwù.', 'Xin vui lòng xác nhận đã hoàn tất toàn bộ nghĩa vụ *thanh toán* cho đơn hàng này chưa.', '[{"chinese":"付款义务","pinyin":"fùkuǎn yìwù","meaning_vi":"nghĩa vụ thanh toán"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-4f9ebfa2c7bd21ef6ae24b15.mp3', 88),
    ('我们已将订单确认函通过邮件发送给您。', 'Wǒmen yǐ jiāng dìngdān quèrèn hán tōngguò yóujiàn fāsòng gěi nín.', 'Chúng tôi đã gửi thư *xác nhận đơn đặt hàng* qua email cho quý khách.', '[{"chinese":"订单确认","pinyin":"dìngdān quèrèn","meaning_vi":"xác nhận đơn đặt hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-7fa0fa01f23f621915a675c2.mp3', 89),
    ('请及时支付定金以确保订单生产优先。', 'Qǐng jíshí zhīfù dìngjīn yǐ quèbǎo dìngdān shēngchǎn yōuxiān.', 'Xin vui lòng thanh toán tiền *đặt cọc* kịp thời để đảm bảo ưu tiên sản xuất đơn hàng.', '[{"chinese":"定金","pinyin":"dìngjīn","meaning_vi":"tiền đặt cọc"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-6a49be3da8fabbd481924ba2.mp3', 90),
    ('双方同意按照约定的付款计划执行付款。', 'Shuāngfāng tóngyì ànzhào yuēdìng de fùkuǎn jìhuà zhíxíng fùkuǎn.', 'Hai bên đồng ý thực hiện thanh toán theo *lịch thanh toán* đã thỏa thuận.', '[{"chinese":"付款计划","pinyin":"fùkuǎn jìhuà","meaning_vi":"lịch thanh toán"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-4bc09a01f17160f347bf3eaf.mp3', 91),
    ('请核对收款账户信息确保资金安全到账。', 'Qǐng héduì shōukuǎn zhànghù xìnxī quèbǎo zījīn ānquán dào zhàng.', 'Xin kiểm tra kỹ thông tin *tài khoản nhận tiền* để đảm bảo vốn an toàn về tài khoản.', '[{"chinese":"收款账户","pinyin":"shōukuǎn zhànghù","meaning_vi":"tài khoản nhận tiền"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-ea0a11eb9acabead4ae88b05.mp3', 92),
    ('请发送付款凭证以便我们及时核实。', 'Qǐng fāsòng fùkuǎn píngzhèng yǐbiàn wǒmen jíshí héshí.', 'Xin vui lòng gửi *chứng từ thanh toán* để chúng tôi kịp thời xác minh.', '[{"chinese":"付款凭证","pinyin":"fùkuǎn píngzhèng","meaning_vi":"chứng từ thanh toán"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-133f6891a7eeeb54423801f4.mp3', 93),
    ('请确认是否已经安排开具正式发票。', 'Qǐng quèrèn shìfǒu yǐjīng ānpái kāijù zhèngshì fāpiào.', 'Xin xác nhận liệu đã sắp xếp xuất *hóa đơn* chính thức chưa.', '[{"chinese":"发票","pinyin":"fāpiào","meaning_vi":"hóa đơn"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-ed881c4e6cdecd0387720b83.mp3', 94),
    ('请确认交货时间和地点是否有所变更。', 'Qǐng quèrèn jiāohuò shíjiān hé dìdiǎn shìfǒu yǒu suǒ biàngēng.', 'Vui lòng xác nhận có thay đổi gì về *lịch giao hàng* và địa điểm không.', '[{"chinese":"交货","pinyin":"jiāohuò","meaning_vi":"giao hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-fb32886645f765543cdba076.mp3', 95),
    ('订单数量变动须提前通知以便双方协调。', 'Dìngdān shùliàng biàndòng xū tíqián tōngzhī yǐbiàn shuāngfāng xiétiáo.', 'Thay đổi *số lượng* đặt hàng cần thông báo trước để hai bên phối hợp.', '[{"chinese":"变动","pinyin":"biàndòng","meaning_vi":"biến động, thay đổi"},{"chinese":"数量","pinyin":"shùliàng","meaning_vi":"số lượng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-fcd10cc3c413e9e1b243657a.mp3', 96),
    ('请定期报告订单的生产和发货进度。', 'Qǐng dìngqī bàogào dìngdān de shēngchǎn hé fāhuò jìndù.', 'Vui lòng báo cáo định kỳ *tiến độ* sản xuất và giao hàng của đơn đặt hàng.', '[{"chinese":"订单","pinyin":"dìngdān","meaning_vi":"đơn hàng"},{"chinese":"进度","pinyin":"jìndù","meaning_vi":"tiến độ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-c40b8277bd403f9c55ad978b.mp3', 97),
    ('因生产延误，交货时间将顺延，请谅解。', 'Yīn shēngchǎn yánwù, jiāohuò shíjiān jiāng shùnyán, qǐng liàngjiě.', 'Do chậm tiến độ sản xuất, *lịch giao hàng* sẽ bị lùi lại, mong quý khách thông cảm.', '[{"chinese":"延误","pinyin":"yánwù","meaning_vi":"trì hoãn"},{"chinese":"交货时间","pinyin":"jiāohuò shíjiān","meaning_vi":"thời gian giao hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-3bb766d9d4ef48a77b8e2e23.mp3', 98),
    ('请确认您已收货且验收合格。', 'Qǐng quèrèn nín yǐ shōuhuò qiě yànshōu hégé.', 'Vui lòng xác nhận quý khách đã nhận hàng và kiểm tra đạt yêu cầu.', '[{"chinese":"验收","pinyin":"yànshōu","meaning_vi":"xác nhận, nghiệm thu"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-6d01ba0a77b1c50517b6edb0.mp3', 99),
    ('请确认本次订单相关款项已全部结清。', 'Qǐng quèrèn běncì dìngdān xiāngguān kuǎnxiàng yǐ quánbù jiéqīng.', 'Xin vui lòng xác nhận các khoản thanh toán liên quan đến đơn hàng này đã được thanh toán hết.', '[{"chinese":"款项","pinyin":"kuǎnxiàng","meaning_vi":"khoản tiền"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-12927fc4362a94c519870cc1.mp3', 100),
    ('请查收随信附上的最新应收账款对账单。', 'Qǐng chá shōu suí xìn fù shàng de zuì xīn yìng shōu zhàng kuǎn duì zhàng dān.', 'Vui lòng kiểm tra bảng đối chiếu công nợ phải thu mới nhất đính kèm trong thư.', '[{"chinese":"应收账款","pinyin":"yìng shōu zhàng kuǎn","meaning_vi":"công nợ phải thu"},{"chinese":"对账单","pinyin":"duì zhàng dān","meaning_vi":"bảng đối chiếu công nợ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-7e4f8dfcd914b8520dd19784.mp3', 101),
    ('请确认贵公司本期应付款项的期初余额。', 'Qǐng quèrèn guì gōngsī běn qī yīng fù kuǎn xiàng de qī chū yú''é.', 'Vui lòng xác nhận số dư đầu kỳ của khoản phải trả công ty quý vị.', '[{"chinese":"应付款项","pinyin":"yīng fù kuǎn xiàng","meaning_vi":"khoản phải trả"},{"chinese":"期初余额","pinyin":"qī chū yú''é","meaning_vi":"số dư đầu kỳ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-45f9cc4d0984ea2e07b084b8.mp3', 102),
    ('请核对附件中的本期应收账款明细。', 'Qǐng héduì fù jiàn zhōng de běn qī yìng shōu zhàng kuǎn míng xì.', 'Vui lòng kiểm tra chi tiết công nợ phải thu của kỳ này trong file đính kèm.', '[{"chinese":"应收账款","pinyin":"yìng shōu zhàng kuǎn","meaning_vi":"công nợ phải thu"},{"chinese":"明细","pinyin":"míng xì","meaning_vi":"chi tiết"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-5588689d687c72cb37f61057.mp3', 103),
    ('请核实贵公司本月应付款项是否准确无误。', 'Qǐng hé shí guì gōngsī běn yuè yīng fù kuǎn xiàng shì fǒu zhǔnquè wú wù.', 'Vui lòng kiểm tra khoản phải trả tháng này của công ty quý vị có chính xác và đầy đủ không.', '[{"chinese":"应付款项","pinyin":"yīng fù kuǎn xiàng","meaning_vi":"khoản phải trả"},{"chinese":"准确","pinyin":"zhǔnquè","meaning_vi":"chính xác"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-08f25596a05348cdd556bc6d.mp3', 104),
    ('我们发现对账单中存在金额差异，请补充相关凭证。', 'Wǒmen fāxiàn duì zhàng dān zhōng cúnzài jīn''é chāyì, qǐng bǔchōng xiāngguān píngzhèng.', 'Chúng tôi phát hiện sự chênh lệch về số tiền trong bảng đối chiếu, xin vui lòng bổ sung chứng từ liên quan.', '[{"chinese":"差异","pinyin":"chāyì","meaning_vi":"sự khác biệt, chênh lệch"},{"chinese":"凭证","pinyin":"píngzhèng","meaning_vi":"chứng từ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-ab6e8c7e6e1bfdcae9091528.mp3', 105),
    ('请说明为什么本次扣款金额低于合同约定数额。', 'Qǐng shuōmíng wèishéme běn cì kòu kuǎn jīn''é dī yú hé tóng yuē dìng shù''é.', 'Vui lòng giải thích tại sao khoản khấu trừ lần này thấp hơn số tiền đã thỏa thuận trong hợp đồng.', '[{"chinese":"扣款金额","pinyin":"kòu kuǎn jīn''é","meaning_vi":"khoản khấu trừ"},{"chinese":"合同约定","pinyin":"hé tóng yuē dìng","meaning_vi":"thỏa thuận hợp đồng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-5c8da3be490b45fb89133590.mp3', 106),
    ('请尽快支付逾期款项以避免影响信用记录。', 'Qǐng jǐnkuài zhīfù yúqī kuǎnxiàng yǐ bìmiǎn yǐngxiǎng xìnyòng jìlù.', 'Vui lòng thanh toán các khoản nợ quá hạn càng sớm càng tốt để tránh ảnh hưởng đến lịch sử tín dụng.', '[{"chinese":"逾期款项","pinyin":"yúqī kuǎnxiàng","meaning_vi":"khoản tiền quá hạn"},{"chinese":"信用记录","pinyin":"xìnyòng jìlù","meaning_vi":"lịch sử tín dụng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-53b9d745915eaf492c6c57a0.mp3', 107),
    ('请提供详细的付款计划以便我们安排资金。', 'Qǐng tígōng xiángxì de fùkuǎn jìhuà yǐbiàn wǒmen ānpái zījīn.', 'Vui lòng cung cấp kế hoạch thanh toán chi tiết để chúng tôi sắp xếp vốn.', '[{"chinese":"付款计划","pinyin":"fùkuǎn jìhuà","meaning_vi":"kế hoạch thanh toán"},{"chinese":"资金","pinyin":"zījīn","meaning_vi":"vốn, tiền"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-e14608b2eadfa9399749b3b5.mp3', 108),
    ('本次对账会生成差异记录，请双方共同确认。', 'Běn cì duì zhàng huì shēng chéng chā yì jì lù, qǐng shuāngfāng gòngtóng quèrèn.', 'Cuộc đối soát lần này sẽ lập biên bản ghi nhận chênh lệch, xin hai bên cùng xác nhận.', '[{"chinese":"差异记录","pinyin":"chā yì jì lù","meaning_vi":"biên bản chênh lệch"},{"chinese":"确认","pinyin":"quèrèn","meaning_vi":"xác nhận"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-135373ca9bd6397acd3e90ba.mp3', 109),
    ('请核对所有发票信息以确保无误。', 'Qǐng héduì suǒyǒu fāpiào xìnxī yǐ quèbǎo wúwù.', 'Vui lòng kiểm tra toàn bộ thông tin hóa đơn để đảm bảo không có sai sót.', '[{"chinese":"发票","pinyin":"fāpiào","meaning_vi":"hóa đơn"},{"chinese":"确保","pinyin":"quèbǎo","meaning_vi":"đảm bảo"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-79dbf3425c8cc71e8df870c1.mp3', 110),
    ('请确认本期所有应收款项已到账。', 'Qǐng quèrèn běn qī suǒyǒu yìng shōu kuǎn xiàng yǐ dào zhàng.', 'Vui lòng xác nhận tất cả khoản phải thu kỳ này đã nhận được tiền.', '[{"chinese":"应收款项","pinyin":"yìng shōu kuǎn xiàng","meaning_vi":"khoản phải thu"},{"chinese":"到账","pinyin":"dào zhàng","meaning_vi":"tiền vào tài khoản"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-3c3339e836eb2d17832973e5.mp3', 111),
    ('有关账目请提供最新的银行对账单。', 'Yǒuguān zhàng mù qǐng tígōng zuìxīn de yínháng duì zhàng dān.', 'Vui lòng cung cấp sao kê ngân hàng mới nhất liên quan đến các tài khoản.', '[{"chinese":"银行对账单","pinyin":"yínháng duì zhàng dān","meaning_vi":"bảng sao kê ngân hàng"},{"chinese":"账目","pinyin":"zhàng mù","meaning_vi":"tài khoản, khoản mục"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-7453b9b7ac285b41d388324d.mp3', 112),
    ('请确认是否需要开具增值税专用发票。', 'Qǐng quèrèn shìfǒu xūyào kāijù zēngzhíshuì zhuānyòng fāpiào.', 'Xin xác nhận có cần xuất hóa đơn giá trị gia tăng chuyên dùng không.', '[{"chinese":"增值税专用发票","pinyin":"zēngzhíshuì zhuānyòng fāpiào","meaning_vi":"hóa đơn giá trị gia tăng chuyên dùng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-507dbb1767d50f18c994b32e.mp3', 113),
    ('请核实订单金额与发票金额是否一致。', 'Qǐng héshí dìngdān jīn''é yǔ fāpiào jīn''é shìfǒu yīzhì.', 'Vui lòng kiểm tra xem số tiền đơn hàng có khớp với số tiền trên hóa đơn hay không.', '[{"chinese":"订单金额","pinyin":"dìngdān jīn''é","meaning_vi":"số tiền đơn hàng"},{"chinese":"一致","pinyin":"yīzhì","meaning_vi":"trùng khớp"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-c9349d9b1e7d4f531b1f7cbe.mp3', 114),
    ('请提供差异部分的详细说明和证明材料。', 'Qǐng tígōng chāyì bùfèn de xiángxì shuōmíng hé zhèngmíng cáiliào.', 'Vui lòng cung cấp giải thích chi tiết và chứng từ cho phần chênh lệch.', '[{"chinese":"差异","pinyin":"chāyì","meaning_vi":"chênh lệch"},{"chinese":"证明材料","pinyin":"zhèngmíng cáiliào","meaning_vi":"chứng từ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-67dbad95ba67a8783324ed88.mp3', 115),
    ('请及时支付欠款以免产生违约责任。', 'Qǐng jíshí zhīfù qiàn kuǎn yǐmiǎn chǎnshēng wéiyuē zérèn.', 'Vui lòng thanh toán khoản nợ đúng hạn để tránh phát sinh trách nhiệm vi phạm hợp đồng.', '[{"chinese":"违约责任","pinyin":"wéiyuē zérèn","meaning_vi":"trách nhiệm vi phạm hợp đồng"},{"chinese":"欠款","pinyin":"qiàn kuǎn","meaning_vi":"khoản nợ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-981fe5b30256516c59c28348.mp3', 116),
    ('请核对收款账户信息以确保资金安全。', 'Qǐng héduì shōu kuǎn zhànghù xìnxī yǐ quèbǎo zījīn ānquán.', 'Vui lòng kiểm tra thông tin tài khoản nhận tiền để đảm bảo an toàn vốn.', '[{"chinese":"收款账户","pinyin":"shōu kuǎn zhànghù","meaning_vi":"tài khoản nhận tiền"},{"chinese":"资金安全","pinyin":"zījīn ānquán","meaning_vi":"an toàn vốn"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-38040191d20d8fba76f4f4c6.mp3', 117),
    ('请发送付款凭证以便我们核实到账情况。', 'Qǐng fāsòng fùkuǎn píngzhèng yǐbiàn wǒmen héshí dào zhàng qíngkuàng.', 'Vui lòng gửi chứng từ thanh toán để chúng tôi đối chiếu số tiền đã nhận.', '[{"chinese":"付款凭证","pinyin":"fùkuǎn píngzhèng","meaning_vi":"chứng từ thanh toán"},{"chinese":"到账情况","pinyin":"dào zhàng qíngkuàng","meaning_vi":"tình trạng nhận tiền"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-354a1cbae6c1ada1208f5e1e.mp3', 118),
    ('请确认订单数量和交货时间是否有变动。', 'Qǐng quèrèn dìngdān shùliàng hé jiāohuò shíjiān shìfǒu yǒu biàndòng.', 'Xin xác nhận liệu số lượng đơn hàng và thời gian giao hàng có thay đổi hay không.', '[{"chinese":"订单数量","pinyin":"dìngdān shùliàng","meaning_vi":"số lượng đơn hàng"},{"chinese":"交货时间","pinyin":"jiāohuò shíjiān","meaning_vi":"thời gian giao hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-b90c3400e4e00bd7667e6bab.mp3', 119),
    ('因运输延误，交货时间将延迟，敬请谅解。', 'Yīn yùnshū yán wù, jiāohuò shíjiān jiāng yánchí, jìng qǐng liàngjiě.', 'Do chậm trễ vận chuyển, thời gian giao hàng sẽ bị trì hoãn, mong quý vị thông cảm.', '[{"chinese":"延误","pinyin":"yánwù","meaning_vi":"chậm trễ"},{"chinese":"交货时间","pinyin":"jiāohuò shíjiān","meaning_vi":"thời gian giao hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-779c3923cfa3526afcfded19.mp3', 120),
    ('订单变更请提前通知以便及时调整账目。', 'Dìngdān biàngēng qǐng tíqián tōngzhī yǐbiàn jíshí tiáozhěng zhàng mù.', 'Xin vui lòng thông báo trước nếu có thay đổi đơn hàng để kịp thời điều chỉnh khoản mục.', '[{"chinese":"订单变更","pinyin":"dìngdān biàngēng","meaning_vi":"thay đổi đơn hàng"},{"chinese":"调整账目","pinyin":"tiáozhěng zhàng mù","meaning_vi":"điều chỉnh tài khoản"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-28d7e06af75d689c55c6eecc.mp3', 121),
    ('请确认已收到全部货物并完成验收。', 'Qǐng quèrèn yǐ shōudào quánbù huòwù bìng wánchéng yànshōu.', 'Vui lòng xác nhận đã nhận đủ tất cả hàng hóa và hoàn tất quá trình kiểm nhận.', '[{"chinese":"验收","pinyin":"yànshōu","meaning_vi":"kiểm nhận"},{"chinese":"货物","pinyin":"huòwù","meaning_vi":"hàng hóa"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-9a23bfb6d1dc6c3d7e2f1e20.mp3', 122),
    ('请确认本期应付账款已全部支付完毕。', 'Qǐng quèrèn běn qī yīng fù zhàng kuǎn yǐ quánbù zhīfù wánbì.', 'Xin xác nhận tất cả khoản phải trả kỳ này đã được thanh toán đầy đủ.', '[{"chinese":"应付账款","pinyin":"yīng fù zhàng kuǎn","meaning_vi":"khoản phải trả"},{"chinese":"支付完毕","pinyin":"zhīfù wánbì","meaning_vi":"thanh toán xong"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-628b17cc45d1a63933fff668.mp3', 123),
    ('请确认双方是否需要签署对账确认书。', 'Qǐng quèrèn shuāngfāng shìfǒu xūyào qiānshǔ duìzhàng quèrènshū.', 'Vui lòng xác nhận hai bên có cần ký biên bản đối soát hay không.', '[{"chinese":"对账确认书","pinyin":"duìzhàng quèrènshū","meaning_vi":"biên bản xác nhận đối soát"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-04e618d69ade49af6bb06361.mp3', 124),
    ('请及时反馈发票开具进度以便对账。', 'Qǐng jíshí fǎnkuì fāpiào kāijù jìndù yǐbiàn duìzhàng.', 'Vui lòng phản hồi kịp thời tiến độ xuất hóa đơn để đối chiếu công nợ.', '[{"chinese":"发票开具","pinyin":"fāpiào kāijù","meaning_vi":"xuất hóa đơn"},{"chinese":"对账","pinyin":"duìzhàng","meaning_vi":"đối chiếu công nợ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-689c977621d1c2616f1f7258.mp3', 125),
    ('我们建议明确代理合作的区域划分以避免冲突。', 'Wǒmen jiànyì míngquè dàilǐ hézuò de qūyù huàfēn yǐ bìmiǎn chōngtú.', 'Chúng tôi đề nghị xác định rõ phân vùng hợp tác đại lý để tránh xung đột.', '[{"chinese":"区域划分","pinyin":"qūyù huàfēn","meaning_vi":"phân vùng khu vực"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-5b76f1670de88adb3ea00d30.mp3', 126),
    ('请确认是否需要我们提供销售支持和市场推广方案。', 'Qǐng quèrèn shìfǒu xūyào wǒmen tígōng xiāoshòu zhīchí hé shìchǎng tuīguǎng fāng''àn.', 'Xin xác nhận liệu quý khách có cần chúng tôi cung cấp hỗ trợ bán hàng và kế hoạch quảng bá thị trường không.', '[{"chinese":"销售支持","pinyin":"xiāoshòu zhīchí","meaning_vi":"hỗ trợ bán hàng"},{"chinese":"市场推广","pinyin":"shìchǎng tuīguǎng","meaning_vi":"quảng bá thị trường"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-07805835b392d42efd831e69.mp3', 127),
    ('我们的售后服务包括产品保修和免费技术咨询。', 'Wǒmen de shòuhòu fúwù bāokuò chǎnpǐn bǎoxiū hé miǎnfèi jìshù zīxún.', 'Dịch vụ hậu mãi của chúng tôi bao gồm bảo hành sản phẩm và tư vấn kỹ thuật miễn phí.', '[{"chinese":"售后服务","pinyin":"shòuhòu fúwù","meaning_vi":"dịch vụ hậu mãi"},{"chinese":"保修","pinyin":"bǎoxiū","meaning_vi":"bảo hành"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-649e3e37eeb075779d3918d8.mp3', 128),
    ('若产品有质量问题，请及时提出换货或退货申请。', 'Ruò chǎnpǐn yǒu zhìliàng wèntí, qǐng jíshí tíchū huànhuò huò tuìhuò shēnqǐng.', 'Nếu sản phẩm có vấn đề về chất lượng, vui lòng kịp thời đề nghị đổi hoặc trả hàng.', '[{"chinese":"换货","pinyin":"huànhuò","meaning_vi":"đổi hàng"},{"chinese":"退货","pinyin":"tuìhuò","meaning_vi":"trả hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-43ca93bb5d9fabc87188b3ef.mp3', 129),
    ('我们已收到您的质量投诉，将尽快调查并提供反馈。', 'Wǒmen yǐ shōudào nín de zhìliàng tóusù, jiāng jǐnkuài diàochá bìng tígōng fǎnkuì.', 'Chúng tôi đã nhận được khiếu nại về chất lượng của quý khách, sẽ nhanh chóng điều tra và cung cấp phản hồi.', '[{"chinese":"质量投诉","pinyin":"zhìliàng tóusù","meaning_vi":"khiếu nại chất lượng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-fd00a2ccb1fc967b72399613.mp3', 130),
    ('请您提供相关证据以便我们核实并处理问题。', 'Qǐng nín tígōng xiāngguān zhèngjù yǐbiàn wǒmen héshí bìng chǔlǐ wèntí.', 'Xin quý khách cung cấp chứng cứ liên quan để chúng tôi xác minh và xử lý vấn đề.', '[{"chinese":"证据","pinyin":"zhèngjù","meaning_vi":"chứng cứ"},{"chinese":"核实","pinyin":"héshí","meaning_vi":"xác minh"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-50eb992e1377c90a13982379.mp3', 131),
    ('为解决问题，我们建议采取以下整改措施。', 'Wèi jiějué wèntí, wǒmen jiànyì cǎiqǔ yǐxià zhěnggǎi cuòshī.', 'Để giải quyết vấn đề, chúng tôi đề nghị áp dụng các biện pháp sửa chữa sau đây.', '[{"chinese":"整改措施","pinyin":"zhěnggǎi cuòshī","meaning_vi":"biện pháp sửa chữa"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-8489c936b28ece33d67e0e23.mp3', 132),
    ('关于赔偿金额，我们愿意在合理范围内协商确定。', 'Guānyú péicháng jīn''é, wǒmen yuànyì zài hélǐ fànwéi nèi xiéshāng quèdìng.', 'Về mức đền bù, chúng tôi sẵn sàng thương lượng trong phạm vi hợp lý để xác định.', '[{"chinese":"赔偿金额","pinyin":"péicháng jīn''é","meaning_vi":"mức tiền bồi thường"},{"chinese":"协商","pinyin":"xiéshāng","meaning_vi":"thương lượng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-ddb0e268f99632ce81c64120.mp3', 133),
    ('若合同条款存在分歧，双方应友好协商解决。', 'Ruò hé​tóng tiáo​kuǎn cún​zài fēn​qí, shuāng​fāng yīng yǒuhǎo xiéshāng jiějué.', 'Nếu có bất đồng trong điều khoản hợp đồng, hai bên nên thương lượng thân thiện để giải quyết.', '[{"chinese":"合同条款","pinyin":"hé​tóng tiáo​kuǎn","meaning_vi":"điều khoản hợp đồng"},{"chinese":"分歧","pinyin":"fēnqí","meaning_vi":"bất đồng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-d158979ccd73f6edaf6dc96c.mp3', 134),
    ('请确认贵公司是否接受此次整改方案的执行。', 'Qǐng quèrèn guì gōngsī shìfǒu jiēshòu cǐ cì zhěnggǎi fāng''àn de zhíxíng.', 'Xin xác nhận công ty quý vị có chấp nhận thực hiện phương án sửa chữa này không.', '[{"chinese":"整改方案","pinyin":"zhěnggǎi fāng''àn","meaning_vi":"phương án sửa chữa"},{"chinese":"执行","pinyin":"zhíxíng","meaning_vi":"thực hiện"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-8819b3bd62ceece74289d9d9.mp3', 135),
    ('我们建议双方签署调解协议以确保争议圆满解决。', 'Wǒmen jiànyì shuāngfāng qiānshǔ tiáojiě xiéyì yǐ quèbǎo zhēngyì yuánmǎn jiějué.', 'Chúng tôi đề nghị hai bên ký thỏa thuận hòa giải để đảm bảo giải quyết tranh chấp trọn vẹn.', '[{"chinese":"调解协议","pinyin":"tiáojiě xiéyì","meaning_vi":"thỏa thuận hòa giải"},{"chinese":"争议","pinyin":"zhēngyì","meaning_vi":"tranh chấp"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-c9823669e917826f96307e4b.mp3', 136),
    ('如需延长售后服务期限，请提前通知我们。', 'Rú xū yáncháng shòuhòu fúwù qīxiàn, qǐng tíqián tōngzhī wǒmen.', 'Nếu cần gia hạn thời gian dịch vụ hậu mãi, xin vui lòng thông báo trước cho chúng tôi.', '[{"chinese":"售后服务期限","pinyin":"shòuhòu fúwù qīxiàn","meaning_vi":"thời hạn dịch vụ hậu mãi"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-83e0948c6b4dfee0b6a58438.mp3', 137),
    ('请提供客户投诉的详细信息以便我们及时处理。', 'Qǐng tígōng kèhù tóusù de xiángxì xìnxī yǐbiàn wǒmen jíshí chǔlǐ.', 'Xin cung cấp thông tin chi tiết về khiếu nại của khách hàng để chúng tôi xử lý kịp thời.', '[{"chinese":"投诉","pinyin":"tóusù","meaning_vi":"khiếu nại"},{"chinese":"详细信息","pinyin":"xiángxì xìnxī","meaning_vi":"thông tin chi tiết"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-8fee695ac1da5fe09aee14d6.mp3', 138),
    ('订单验收完成后，请双方签署确认文件。', 'Dìngdān yànshōu wánchéng hòu, qǐng shuāngfāng qiānshǔ quèrèn wénjiàn.', 'Sau khi hoàn thành nghiệm thu đơn hàng, xin hai bên ký xác nhận văn bản.', '[{"chinese":"验收","pinyin":"yànshōu","meaning_vi":"nghiệm thu"},{"chinese":"确认文件","pinyin":"quèrèn wénjiàn","meaning_vi":"văn bản xác nhận"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-228701a683389f86ee543c0c.mp3', 139),
    ('请确认换货申请已符合相关政策和流程。', 'Qǐng quèrèn huànhuò shēnqǐng yǐ fúhé xiāngguān zhèngcè hé liúchéng.', 'Vui lòng xác nhận đơn xin đổi hàng đã phù hợp với chính sách và quy trình liên quan.', '[{"chinese":"换货申请","pinyin":"huànhuò shēnqǐng","meaning_vi":"đơn xin đổi hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-e59721c504e5b3ff8f7fee59.mp3', 140),
    ('因产品缺陷引发的纠纷，双方应协商寻求解决方案。', 'Yīn chǎnpǐn quēxiàn yǐnfā de jiūfēn, shuāngfāng yīng xiéshāng xúnqiú jiějué fāng''àn.', 'Các tranh chấp phát sinh do lỗi sản phẩm, hai bên nên thương lượng tìm phương án giải quyết.', '[{"chinese":"纠纷","pinyin":"jiūfēn","meaning_vi":"tranh chấp"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-8fffc85c30cc50ffb319eb34.mp3', 141),
    ('请核实您的区域是否符合我们的市场分销政策。', 'Qǐng héshí nín de qūyù shìfǒu fúhé wǒmen de shìchǎng fēnxiāo zhèngcè.', 'Xin xác minh khu vực của quý vị có phù hợp với chính sách phân phối thị trường của chúng tôi không.', '[{"chinese":"分销政策","pinyin":"fēnxiāo zhèngcè","meaning_vi":"chính sách phân phối"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-919a03293c9d1fa87fe48090.mp3', 142),
    ('如果对解决方案有异议，请及时反馈以便调整。', 'Rúguǒ duì jiějué fāng''àn yǒu yìyì, qǐng jíshí fǎnkuì yǐbiàn tiáozhěng.', 'Nếu có ý kiến khác về phương án giải quyết, xin phản hồi kịp thời để điều chỉnh.', '[{"chinese":"异议","pinyin":"yìyì","meaning_vi":"ý kiến khác"},{"chinese":"反馈","pinyin":"fǎnkuì","meaning_vi":"phản hồi"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-a8b623127573a03fc65e3131.mp3', 143),
    ('请提供争议事件的相关文档以便双方审核。', 'Qǐng tígōng zhēngyì shìjiàn de xiāngguān wéndàng yǐbiàn shuāngfāng shěnhé.', 'Vui lòng cung cấp các tài liệu liên quan đến sự kiện tranh chấp để hai bên kiểm tra.', '[{"chinese":"争议事件","pinyin":"zhēngyì shìjiàn","meaning_vi":"sự kiện tranh chấp"},{"chinese":"文档","pinyin":"wéndàng","meaning_vi":"tài liệu"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-3549f8679302c4a96f240e4a.mp3', 144),
    ('双方达成协议后，请尽快签字盖章完成手续。', 'Shuāngfāng dáchéng xiéyì hòu, qǐng jǐnkuài qiānzì gàizhāng wánchéng shǒuxù.', 'Sau khi hai bên đạt được thỏa thuận, xin nhanh chóng ký tên và đóng dấu hoàn thành thủ tục.', '[{"chinese":"签字盖章","pinyin":"qiānzì gàizhāng","meaning_vi":"ký tên đóng dấu"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-e6b729a0fe5fc2360174fb30.mp3', 145),
    ('请及时支付拖欠款项以避免产生额外的法律责任。', 'Qǐng jíshí zhīfù tuōqiàn kuǎnxiàng yǐ bìmiǎn chǎnshēng éwài de fǎlǜ zérèn.', 'Xin thanh toán các khoản nợ trễ hạn kịp thời để tránh phát sinh trách nhiệm pháp lý thêm.', '[{"chinese":"拖欠款项","pinyin":"tuōqiàn kuǎnxiàng","meaning_vi":"khoản tiền nợ trễ hạn"},{"chinese":"法律责任","pinyin":"fǎlǜ zérèn","meaning_vi":"trách nhiệm pháp lý"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-150-cau/sentence-59fcf69520bbda499b3b53ea.mp3', 146),
